                        <td>@course.Schedule</td>
                    </tr>
                    <tr>
                        <th>Credits</th>
                        <td>@course.Credits</td>
                    </tr>
                    <tr>
                        <th>Department</th>
                        <td>@department?.Code — @department?.Name</td>
                    </tr>
                </tbody>
            </table>

            <a href="@($"enroll?courseId={course.Id}")" class="btn btn-success mt-2">Request Enrollment</a>
        </div>

        <div class="col-md-4">
            @if (instructor is not null)
            {
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">Instructor</h5>
                        <h6>@instructor.Name</h6>
