@page "/enroll"
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Request Enrollment</h1>
<p>Fill out the form below to request enrollment in a course.</p>

@if (Submitted)
{
    var selectedCourse = Catalog.GetCourse(Model.CourseId);
    <div class="alert alert-success">
        <h4 class="alert-heading">Enrollment Request Submitted</h4>
        <p>Thank you, <strong>@Model.StudentName</strong> (ID: @Model.StudentId).</p>
        <p>Your enrollment request for <strong>@selectedCourse?.Code — @selectedCourse?.Title</strong> has been received and will be reviewed by the registrar.</p>
        <hr />
        <a href="courses" class="btn btn-outline-success">Browse More Courses</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-8 col-lg-6">
            <form method="post" data-enhance>
                <AntiforgeryToken />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName" class="form-control" />
                    @if (errors.ContainsKey(nameof(Model.StudentName)))
                    {
                        <div class="text-danger small mt-1">@errors[nameof(Model.StudentName)]</div>
                    }
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" class="form-control" />
                    @if (errors.ContainsKey(nameof(Model.StudentId)))
                    {
                        <div class="text-danger small mt-1">@errors[nameof(Model.StudentId)]</div>
                    }
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <select id="courseId" name="Model.CourseId" class="form-select">
                        <option value="0">— Select a course —</option>
                        @foreach (var course in Catalog.GetAllCourses())
                        {
                            if (course.Id == Model.CourseId)
                            {
                                <option value="@course.Id" selected>@course.Code — @course.Title</option>
                            }
                            else
                            {
                                <option value="@course.Id">@course.Code — @course.Title</option>
                            }
                        }
                    </select>
                    @if (errors.ContainsKey(nameof(Model.CourseId)))
                    {
                        <div class="text-danger small mt-1">@errors[nameof(Model.CourseId)]</div>
                    }
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
            </form>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private bool Submitted { get; set; }
    private Dictionary<string, string> errors = new();

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        if (HttpMethods.IsPost(HttpContext?.Request.Method ?? "GET"))
        {
            errors = Validate(Model);
            if (errors.Count == 0)
            {
                Submitted = true;
            }
        }
    }

    [CascadingParameter]
    private HttpContext? HttpContext { get; set; }

    private static Dictionary<string, string> Validate(EnrollmentRequest model)
    {
        var results = new Dictionary<string, string>();
        var context = new System.ComponentModel.DataAnnotations.ValidationContext(model);
        var validationResults = new List<System.ComponentModel.DataAnnotations.ValidationResult>();

        if (!System.ComponentModel.DataAnnotations.Validator.TryValidateObject(model, context, validationResults, validateAllProperties: true))
        {
            foreach (var vr in validationResults)
            {
                foreach (var member in vr.MemberNames)
                {
                    results.TryAdd(member, vr.ErrorMessage ?? "Invalid value.");
                }
            }
        }

        return results;
    }
}

